package net.battlespades.bot;
import java.nio.file.Path;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.world.PrefabModels;
import static net.battlespades.bot.BotFoundationsTest.*;
import static net.battlespades.bot.BotPlayerTestData.player;
import static net.battlespades.bot.BotPerceptionTestData.*;
import static net.battlespades.bot.BotSourceFixture.*;
import static net.battlespades.bot.BotState.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BotCooperativeTest {
 static final Map<String,Object> SOURCE=read("bot-cooperative");
 static List<BotPrefabPolicy.Geometry> geometry()throws Exception{return BotPrefabPolicy.load(list(SOURCE.get("geometry")).stream().map(o->string(map(o).get("name"))).toList(),new PrefabModels(List.of(Path.of("..","prefabs"))));}
 static BotNavigationWorld world()throws Exception{var w=new BotNavigationWorld();w.load(new MapSnapshot(7,0,BotNavigationTest.raw(SOURCE.get("raw_zlib")),"tdm","",List.of(),"retail").withPrefabs(geometry()));return w;}
 static void delta(BotNavigationWorld w,Object o){var s=map(o);w.apply(new WorldDelta(7,number(s.get("version")),list(s.get("cells")).stream().map(v->{var a=list(v);return new VoxelChange(integer(a.get(0)),integer(a.get(1)),integer(a.get(2)),bool(a.get(3)),integer(a.get(4)),real(a.get(5)));}).toList()));}
 @Test void authoredPrefabFactsSurviveSnapshotRebaseAndRealKv6Expansion()throws Exception{var shapes=geometry();assertEquals(16,shapes.size());for(int i=0;i<shapes.size();i++){var s=shapes.get(i);var expected=map(list(SOURCE.get("geometry")).get(i));matches(expected.get("name"),s.name());matches(expected.get("block_count"),s.blockCount());matches(expected.get("cells_by_yaw"),s.cellsByYaw());matches(expected.get("bounds_by_yaw"),s.boundsByYaw().stream().map(b->List.of(b.minimum(),b.maximum())).toList());}var snapshot=new MapSnapshot(7,0,new byte[0],"tdm","",List.of(),"retail").withPrefabs(shapes);assertEquals(shapes,snapshot.rebase(1,List.of()).prefabGeometry());assertThrows(UnsupportedOperationException.class,()->snapshot.prefabGeometry().clear());}
 @Test void boundedGeometryProposalsMatchActualSourceTerrain()throws Exception{var w=world();for(var o:list(SOURCE.get("projects"))){var trace=map(o);delta(w,trace.get("scene"));int index=0;for(var v:list(trace.get("rows"))){var r=map(v);var p=player(r.get("observer"));var lane=vector(r.get("lane"));var friends=list(r.get("friends")).stream().map(BotFoundationsTest::vector).toList();var reserved=new HashSet<>(list(r.get("reserved")).stream().map(BotFoundationsTest::cell).toList());try{matches(r.get("sniper"),ProjectSites.sniper(w,p,lane,friends,reserved));matches(r.get("cover"),ProjectSites.cover(w,p,lane,false,friends,reserved));matches(r.get("rear"),ProjectSites.cover(w,p,lane,true,friends,reserved));matches(r.get("bridge"),ProjectSites.bridge(w,p,lane,reserved));matches(r.get("mine"),ProjectSites.mine(w,p,lane,friends,reserved));matches(r.get("breach"),ProjectSites.breach(w,p,lane,reserved));matches(r.get("decoration"),ProjectSites.decoration(w,p,friends,reserved));matches(r.get("rampart"),ProjectSites.rampart(w,p,new Vector(245.5,245.5,97.75),friends,reserved,4,2));}catch(AssertionError e){throw new AssertionError(map(trace.get("scene")).get("name")+" geometry "+index,e);}index++;}}}
 static final Comparator<Cell> CELLS=Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y).thenComparingInt(Cell::z);
 static Map<String,Object> placement(BotSchematic.Placement p){if(p==null)return null;var r=new LinkedHashMap<String,Object>();r.put("name",p.name());r.put("anchor",p.anchor());r.put("rotation",p.rotation());r.put("cells",p.cells().entrySet().stream().map(e->Map.of("cell",e.getKey(),"color",e.getValue())).toList());r.put("foundation",p.foundation().stream().sorted(CELLS).toList());r.put("clear",p.clear().stream().sorted(CELLS).toList());r.put("columns",p.columns().stream().sorted(Comparator.comparingInt(ProjectSites.Column::x).thenComparingInt(ProjectSites.Column::y)).map(c->List.of(c.x(),c.y())).toList());r.put("occupant",p.occupant());return r;}
 static Map<String,Object> plan(SchematicPlanning.Plan p){var r=new LinkedHashMap<String,Object>();r.put("steps",p.steps());r.put("unbuildable",p.unbuildable());r.put("region",p.region());r.put("estimated_seconds",p.estimatedSeconds());r.put("walk_cells",p.walkCells());var indices=new ArrayList<Object>();for(var step:p.steps())for(var cell:step.cells())indices.add(Map.of("cell",cell,"index",step.index()));r.put("cell_step",indices);r.put("feasible",p.feasible());r.put("cost",p.cost());r.put("lines",p.lines());r.put("singles",p.singles());r.put("line_cells",p.lineCells());return r;}
 @Test void schematicFitsAndSupportedBlockLinePlansMatchAllSourceRotations()throws Exception{var w=world();var reader=RecoveryPlanning.reader(w);for(var o:list(SOURCE.get("schematics"))){var r=map(o);String name=string(r.get("name"));int rotation=integer(r.get("rotation"));try{var shape=Objects.requireNonNull(SchematicLibrary.get(name));var fit=shape.fit(reader,new ProjectSites.Column(245,245),100,rotation,0);matches(r.get("reason"),fit.reason());matches(r.get("placement"),placement(fit.placement()));if(fit.placement()!=null){var plan=SchematicPlanning.plan(reader,fit.placement(),8,5.5,false,3,true);matches(r.get("plan"),plan(plan));matches(r.get("problems"),SchematicPlanning.validate(reader,plan,8,5.5));}}catch(AssertionError e){throw new AssertionError(name+" rotation "+rotation,e);}}}
 @Test void cooperativeTasksConfirmActionsBeforeUsingProjectsAndRetainInterruptions()throws Exception{for(var o:list(SOURCE.get("cooperative"))){var trace=map(o);var w=world();var coop=new CooperativeBehavior(w);int index=0;for(var v:list(trace.get("events"))){var r=map(v);try{switch(string(r.get("op"))){case "delta"->delta(w,r);case "request"->{var site=coop.requestSchematic(integer(r.get("team")),string(r.get("shape")),vector(r.get("anchor")),real(r.get("now")),new Vector(1,0,0),integer(r.get("rotation")),true,Set.of(),.95,90,"strategy","");matches(r.get("result"),site==null?null:site.status(RecoveryPlanning.reader(w)));}case "decide"->{var p=player(r.get("observer"));matches(r.get("result"),coop.decide(frame(r.get("frame")),p,r.get("visible")==null?null:player(r.get("visible")),decision(r.get("strategic"))));matches(r.get("state"),coop.snapshot(p));}default->fail("Unknown source event");}}catch(AssertionError e){throw new AssertionError(trace.get("name")+" cooperative boundary "+index,e);}index++;}}}
}
